78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        if (!normalizeNewOwner(owner)) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        if (dailyLimitReached(owner.getRegistrationDate())) {
112	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
113	        }
114	        if (cityIsAtCapacity(owner.getCity())) {
115	            return new ResponseEntity<>(HttpStatus.CONFLICT);
116	        }
117	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        Optional<Owner> householdMember = findHouseholdMember(owner);
121	        if (householdMember.isPresent()) {
122	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
123	                return new ResponseEntity<>(HttpStatus.CONFLICT);
124	            }
125	            joinHousehold(owner, householdMember.get());
126	        }
127	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
128	        owner.setNamesakeCount(countNamesakes(owner));
129	        owner.setMembershipNumber(membershipNumber(owner));
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
140	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
141	        if (currentOwner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        currentOwner.setAddress(ownerFieldsDto.getAddress());
145	        currentOwner.setCity(ownerFieldsDto.getCity());
146	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
147	        currentOwner.setLastName(ownerFieldsDto.getLastName());
148	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
149	        String email = ownerFieldsDto.getEmail();
150	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
151	        this.clinicService.saveOwner(currentOwner);
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Transactional
157	    @Override
158	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
