217	
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner != null) {
224	            Pet pet = owner.getPet(petId);
225	            if (pet != null) {
226	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
231	
232	    /**
233	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
234	     * the canonical form each stored value must take: the address is trimmed,
235	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
236	     * telephone is converted to E.164, any email is lower-cased and a missing
237	     * registration date defaults to today. Field-level rejections are reported here
238	     * rather than inline in {@link #addOwner}, and normalisation runs before any
239	     * household comparison so those comparisons see the canonical values.
240	     *
241	     * @param owner the freshly-mapped owner to normalise
242	     * @return {@code true} if the fields are valid, or {@code false} if the address
243	     *         is blank after normalisation or the telephone cannot form a valid
244	     *         E.164 number, in which case the request must be rejected with
245	     *         {@code 400 Bad Request}
246	     */
247	    private boolean normalizeNewOwner(Owner owner) {
248	        String address = Owner.normalizeAddress(owner.getAddress());
249	        if (address.isEmpty()) {
250	            return false;
251	        }
252	        owner.setAddress(address);
253	        String telephone = toE164(owner.getTelephone());
254	        if (telephone == null) {
255	            return false;
256	        }
257	        owner.setTelephone(telephone);
258	        if (owner.getEmail() != null) {
259	            owner.setEmail(owner.getEmail().toLowerCase());
260	        }
261	        if (owner.getRegistrationDate() == null) {
262	            owner.setRegistrationDate(LocalDate.now());
263	        }
264	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
265	        return true;
266	    }
267	
268	    /**
269	     * Roll the given date forward to the next business day when it falls on a
270	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
271	     * weekday is returned unchanged. Applied to the effective registration date
272	     * (whether supplied in the request or defaulted to the server date) so that
273	     * every value derived from it uses the adjusted business day.
274	     *
275	     * @param date the effective registration date
276	     * @return the same date if it is a weekday, otherwise the next Monday
277	     */
278	    private static LocalDate rollToBusinessDay(LocalDate date) {
279	        switch (date.getDayOfWeek()) {
280	            case SATURDAY:
281	                return date.plusDays(2);
282	            case SUNDAY:
283	                return date.plusDays(1);
284	            default:
285	                return date;
286	        }
287	    }
288	
289	    /**
290	     * Find an existing owner that belongs to the same household as the given owner,
291	     * i.e. shares the same last name and address (compared case-insensitively with
292	     * runs of whitespace collapsed to a single space).
293	     *
294	     * @param owner the candidate owner being created
295	     * @return the matching existing owner, or empty if none exists
296	     */
297	    private Optional<Owner> findHouseholdMember(Owner owner) {
298	        return this.clinicService.findAllOwners().stream()
299	            .filter(existing -> existing.sameHouseholdAs(owner))
300	            .findFirst();
301	    }
302	
303	    /**
304	     * Assign the joining owner and an existing household member the same stable
305	     * household identifier. The identifier is derived deterministically from the
306	     * shared household key (last name + address, normalised), so every owner in a
307	     * household resolves to the same value; the existing member is updated when it
308	     * does not already carry it.
309	     *
310	     * @param owner    the owner being created
311	     * @param existing an existing owner in the same household
312	     */
313	    private void joinHousehold(Owner owner, Owner existing) {
314	        String householdId = UUID
315	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
316	        owner.setHouseholdId(householdId);
317	        if (!householdId.equals(existing.getHouseholdId())) {
318	            existing.setHouseholdId(householdId);
319	            this.clinicService.saveOwner(existing);
320	        }
321	    }
322	
323	    /**
324	     * Count the existing owners that share the given owner's first and last name,
325	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
326	     * before the new owner is saved, so the result reflects only owners that
327	     * already existed at creation time.
328	     *
329	     * @param owner the candidate owner being created
330	     * @return the number of existing namesakes
331	     */
332	    private int countNamesakes(Owner owner) {
333	        String firstName = normalizeName(owner.getFirstName());
334	        String lastName = normalizeName(owner.getLastName());
335	        return (int) this.clinicService.findAllOwners().stream()
336	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
337	                && normalizeName(existing.getLastName()).equals(lastName))
338	            .count();
339	    }
340	
341	    private static String normalizeName(String value) {
342	        return value == null ? "" : value.trim().toLowerCase();
343	    }
344	
345	    /**
346	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
347	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
348	     * first three letters of the given last name and NNNN a per-city 4-digit
349	     * zero-padded sequence equal to one more than the number of owners already in
350	     * that city (e.g. {@code SYD-SMI-0007}).
351	     *
352	     * @param city     the owner's city
353	     * @param lastName the owner's last name
354	     * @return the assigned customer code
355	     */
356	    /**
357	     * Determine whether the given city has already reached its owner capacity, i.e.
358	     * it already contains 50 or more existing owners (compared case-insensitively
359	     * with surrounding whitespace trimmed). A new owner may not be created in a city
360	     * that is at capacity.
361	     *
362	     * @param city the candidate owner's city
363	     * @return {@code true} if the city already holds 50 or more owners
364	     */
365	    private boolean cityIsAtCapacity(String city) {
366	        String normalizedCity = normalizeName(city);
367	        long count = this.clinicService.findAllOwners().stream()
368	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
369	            .count();
370	        return count >= 50;
371	    }
372	
373	    /**
374	     * Determine whether the daily owner-creation limit has already been reached, i.e.
375	     * 100 or more owners already carry the given registration date. A new owner may
376	     * not be created once that day's cap is reached.
377	     *
378	     * @param registrationDate the registration date the new owner would be created with
379	     * @return {@code true} if 100 or more existing owners share that registration date
380	     */
381	    private boolean dailyLimitReached(LocalDate registrationDate) {
382	        long count = this.clinicService.findAllOwners().stream()
383	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
384	            .count();
385	        return count >= 100;
386	    }
387	
388	    private String nextCustomerCode(String city, String lastName) {
389	        String city3 = prefix3(city);
390	        String last3 = prefix3(lastName);
391	        long sequence = this.clinicService.findAllOwners().stream()
392	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(city)))
393	            .count() + 1L;
394	        return String.format("%s-%s-%04d", city3, last3, sequence);
395	    }
396	
397	    private static String prefix3(String value) {
398	        String v = value == null ? "" : value;
399	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
400	    }
401	
402	    /**
403	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
404	     * where {@code <customerCode>} is the owner's already-assigned customer code and
405	     * YY is the last two digits of the registration date's year (e.g.
406	     * {@code SMI-0007-M26}). Evaluated after the customer code and registration date
407	     * have been set.
408	     *
409	     * @param owner the owner being created, with customer code and registration date
410	     *              already assigned
411	     * @return the assigned membership number
412	     */
413	    private String membershipNumber(Owner owner) {
414	        int yy = owner.getRegistrationDate().getYear() % 100;
415	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
416	    }
417	
418	    /**
419	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
420	     * code when present, otherwise assume country code '+61' and drop a single
421	     * leading '0' from the national digits. Spaces, dashes and brackets are
422	     * stripped. The result must contain 8 to 15 digits after the '+'.
423	     *
424	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
425	     *         input cannot form a valid E.164 number.
426	     */
427	    private static String toE164(String raw) {
428	        if (raw == null) {
429	            return null;
430	        }
431	        String cleaned = raw.replaceAll("[\\s()-]", "");
432	        String digits;
433	        if (cleaned.startsWith("+")) {
434	            digits = cleaned.substring(1);
435	        } else {
436	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
437	            digits = "61" + national;
438	        }
439	        if (!digits.matches("\\d{8,15}")) {
440	            return null;
441	        }
442	        return "+" + digits;
443	    }
444	}
